Section 4 — Gouraud scanline rasterizer (pixel-center sampling; vertex colors interpolated along the two edges, then across each span). Implement EXACTLY:
function drawTriangle(v0, v1, v2) {
  let a = v0, b = v1, c = v2, t;
  if (a.y > b.y) { t = a; a = b; b = t; }
  if (b.y > c.y) { t = b; b = c; c = t; }
  if (a.y > b.y) { t = a; a = b; b = t; }
  if (c.y - a.y < 1e-6) return;
  const invH = 1 / (c.y - a.y);
  const yS = Math.max(0, Math.ceil(a.y - 0.5));
  const yE = Math.min(H - 1, Math.ceil(c.y - 0.5) - 1);
  for (let py = yS; py <= yE; py++) {
    const sy = py + 0.5;
    const ta = Math.min(1, Math.max(0, (sy - a.y) * invH)); // long edge a->c
    let xl = a.x + (c.x - a.x) * ta, rl = a.r + (c.r - a.r) * ta,
        gl = a.g + (c.g - a.g) * ta, bl = a.b + (c.b - a.b) * ta;
    let xr, rr, gr, br; // short edge
    if (sy < b.y) {
      if (b.y - a.y < 1e-6) continue;
      const tb = (sy - a.y) / (b.y - a.y);
      xr = a.x + (b.x - a.x) * tb; rr = a.r + (b.r - a.r) * tb;
      gr = a.g + (b.g - a.g) * tb; br = a.b + (b.b - a.b) * tb;
    } else {
      if (c.y - b.y < 1e-6) continue;
      const tb = (sy - b.y) / (c.y - b.y);
      xr = b.x + (c.x - b.x) * tb; rr = b.r + (c.r - b.r) * tb;
      gr = b.g + (c.g - b.g) * tb; br = b.b + (c.b - b.b) * tb;
    }
    if (xl > xr) { let s; s = xl; xl = xr; xr = s; s = rl; rl = rr; rr = s; s = gl; gl = gr; gr = s; s = bl; bl = br; br = s; }
    const dx = xr - xl;
    const xS = Math.max(0, Math.ceil(xl - 0.5));
    const xE = Math.min(W - 1, Math.ceil(xr + 1e-4 - 0.5) - 1);
    let i = (py * W + xS) * 4;
    for (let px = xS; px <= xE; px++, i += 4) {
      const s = dx > 1e-6 ? (px + 0.5 - xl) / dx : 0;
      data[i] = rl + (rr - rl) * s;
      data[i + 1] = gl + (gr - gl) * s;
      data[i + 2] = bl + (br - bl) * s;
      data[i + 3] = 255;
    }
  }
}

