function renderScene() {
  buf32.fill(BG32);
  // ---- rotation matrices: R = Ry(ay) * Rx(ax), stored flat ----
  const ax = simTime * 0.55, ay = simTime * 0.85;
  const cxA = Math.cos(ax), sxA = Math.sin(ax), cyA = Math.cos(ay), syA = Math.sin(ay);
  const m00 = cyA,     m01 = syA * sxA, m02 = syA * cxA,
        m10 = 0,       m11 = cxA,       m12 = -sxA,
        m20 = -syA,    m21 = cyA * sxA, m22 = cyA * cxA;
  // ---- transform vertices: model -> world -> screen (perspective) ----
  const world = [], screen = [];
  for (let i = 0; i < 8; i++) {
    const v = CUBE_VERTS[i];
    const wx = m00 * v[0] + m01 * v[1] + m02 * v[2];
    const wy = m10 * v[0] + m11 * v[1] + m12 * v[2];
    const wz = m20 * v[0] + m21 * v[1] + m22 * v[2];
    const vz = wz - CAM_Z;
    world.push({ x: wx, y: wy, z: wz });
    screen.push({ x: W / 2 + wx * focal / vz, y: H / 2 - wy * focal / vz, vz: vz });
  }
  // ---- moving point light (world space) ----
  const lx = 3.4 * Math.sin(simTime * 0.7);
  const ly = 1.8 * Math.sin(simTime * 1.1 + 1.2);
  const lz = 2.6 * Math.cos(simTime * 0.7) - 1.4;
  // ---- per-face: world normal, backface culling, depth sort ----
  const visible = [];
  for (const f of FACES) {
    const A = world[f.q[0]], B = world[f.q[1]], C = world[f.q[2]];
    let nx = (B.y - A.y) * (C.z - A.z) - (B.z - A.z) * (C.y - A.y);
    let ny = (B.z - A.z) * (C.x - A.x) - (B.x - A.x) * (C.z - A.z);
    let nz = (B.x - A.x) * (C.y - A.y) - (B.y - A.y) * (C.x - A.x);
    const nl = Math.hypot(nx, ny, nz); nx /= nl; ny /= nl; nz /= nl;
    const vx = A.x - 0, vy = A.y - 0, vzz = A.z - CAM_Z; // view vector vertex->camera
    if (nx * vx + ny * vy + nz * vzz >= 0) continue; // backface cull (dot(normal, toCamera) < 0 required)
    const depth = (screen[f.q[0]].vz + screen[f.q[1]].vz + screen[f.q[2]].vz + screen[f.q[3]].vz) / 4;
    visible.push({ f, n: [nx, ny, nz], depth });
  }
  visible.sort((p, q) => q.depth - p.depth); // painter: far first
  // ---- per-triangle Gouraud: Lambert lighting at each vertex, then rasterize ----
  const AMBIENT = 0.16, DIFFUSE = 0.9;
  for (const item of visible) {
    const f = item.f, n = item.n;
    const tris = [[f.q[0], f.q[1], f.q[2]], [f.q[0], f.q[2], f.q[3]]];
    for (const tri of tris) {
      const tv = [];
      for (const id of tri) {
        const p = world[id], s = screen[id];
        let Lx = lx - p.x, Ly = ly - p.y, Lz = lz - p.z;
        const ll = Math.hypot(Lx, Ly, Lz); Lx /= ll; Ly /= ll; Lz /= ll;
        const d = Math.max(0, n[0] * Lx + n[1] * Ly + n[2] * Lz);
        const I = AMBIENT + DIFFUSE * d;
        tv.push({ x: s.x, y: s.y, r: f.col[0] * I, g: f.col[1] * I, b: f.col[2] * I });
      }
      drawTriangle(tv[0], tv[1], tv[2]);
    }
  }
  ctx.putImageData(img, 0, 0);
  // ---- wireframe overlay (shows the triangle split incl. diagonals) ----
  if (wireframe) {
    ctx.strokeStyle = 'rgba(255,255,255,0.30)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (const item of visible) {
      const q = item.f.q;
      ctx.moveTo(screen[q[0]].x, screen[q[0]].y);
      ctx.lineTo(screen[q[1]].x, screen[q[1]].y);
      ctx.lineTo(screen[q[2]].x, screen[q[2]].y);
      ctx.lineTo(screen[q[3]].x, screen[q[3]].y);
      ctx.closePath();
      ctx.moveTo(screen[q[0]].x, screen[q[0]].y);
      ctx.lineTo(screen[q[2]].x, screen[q[2]].y);
    }
    ctx.stroke();
  }
  // ---- glowing marker at the light position ----
  const lvz = lz - CAM_Z;
  if (lvz > 0.2) {
    const msx = W / 2 + lx * focal / lvz, msy = H / 2 - ly * focal / lvz;
    const g = ctx.createRadialGradient(msx, msy, 0, msx, msy, 30);
    g.addColorStop(0, 'rgba(255,240,200,0.85)');
    g.addColorStop(1, 'rgba(255,240,200,0)');
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(msx, msy, 30, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
  }
}

Section 6 — main loop with FPS counter (updates the DOM every 500 ms):
let last = 0, fpsLast = 0, fpsFrames = 0;
function frame(ts) {
  if (!last) last = ts;
  const dt = Math.min(0.05, (ts - last) / 1000);
  last = ts;
  if (!paused) simTime += dt;
  renderScene();
  fpsFrames++;
  if (!fpsLast) fpsLast = ts;
  else if (ts - fpsLast >= 500) {
    fpsEl.textContent = String(Math.round(fpsFrames * 1000 / (ts - fpsLast)));
    fpsFrames = 0; fpsLast = ts;
  }
  requestAnimationFrame(frame);
}
updateStatus();
requestAnimationFrame(frame);

